import {MatchClient,$,escape} from './client.js';
import {CLUBS,HOLES} from '/shared/golf.js';
import {ClubSwing,rotationSpeed} from '/shared/club-swing.js';
import {MotionAim,rotationMatrix} from '/shared/motion-aim.js';
let session=null,match=null,me=null,aim=0,club='driver',turnKey=-1,turnAim=false,orientation=null,orientationAt=0,motionAt=0,pointer=null,lockedAim=0,lockedClub='driver',sending=false,lastSent=null;
const meter=new ClubSwing(),steer=new MotionAim();let gyroAt=-Infinity,lastSensorSource='';
function error(message){$('phone-error').textContent=message;if($('swing-feedback'))$('swing-feedback').textContent=message;}
const client=new MatchClient(render,error);
try{session=JSON.parse(sessionStorage.getItem('fairway.pvp.player'));}catch{}
$('code').value=new URLSearchParams(location.search).get('code')??session?.code??'';$('name').value=session?.name??'';
async function permission(){try{const requests=[];for(const type of [globalThis.DeviceMotionEvent,globalThis.DeviceOrientationEvent])if(typeof type?.requestPermission==='function')requests.push(type.requestPermission());const results=await Promise.all(requests);if(results.some(r=>r==='denied'))error('Motion access was denied. You can still use Touch shot below.');navigator.wakeLock?.request('screen').catch(()=>{});}catch{error('Motion permission was not granted. Touch controls are available.');}}
function canPlay(){return client.online&&!sending&&match?.phase==='ready'&&match.turn===session?.playerId&&!me?.forfeit;}
function aimUI(){$('aim').value=aim;$('aimlabel').textContent=aim?`${Math.abs(aim).toFixed(1)}° ${aim>0?'left':'right'}`:'at the flag';$('motionaim').textContent=turnAim?'Turn to aim: ON':'Turn to aim';$('recenter').disabled=!turnAim||!canPlay()||meter.active;}
function recenter(value=0){if(!orientation||performance.now()-orientationAt>1500){error('No orientation readings yet. Allow motion access or use the slider.');return;}steer.recenter(orientation,value);aim=value;lastSent=null;aimUI();}
async function join(){await permission();const code=$('code').value.trim().toUpperCase(),name=$('name').value.trim()||'Golfer';const r=await client.action({op:'join',code,name,token:session?.code===code?session.token:undefined});if(!r)return;session={code,token:r.token,playerId:r.playerId,name};sessionStorage.setItem('fairway.pvp.player',JSON.stringify(session));$('join').hidden=true;$('controller').hidden=false;client.start({code,token:r.token});render(r.match);}
$('connect').onclick=join;$('enable').onclick=permission;
$('ready').onclick=()=>client.action({op:'ready',ready:!me?.ready});
$('clubs').innerHTML=Object.entries(CLUBS).map(([id,c])=>`<button data-club="${id}">${c.label}</button>`).join('');
document.querySelectorAll('[data-club]').forEach(b=>b.onclick=()=>{if(!canPlay()||meter.active)return;club=b.dataset.club;client.action({op:'club',club,turnNumber:match.turnNumber});controls();});
$('aim').oninput=()=>{if(!canPlay()||meter.active)return;turnAim=false;aim=Number($('aim').value);lastSent=null;aimUI();};
$('motionaim').onclick=async()=>{if(meter.active)return;turnAim=!turnAim;if(turnAim){await permission();recenter(aim);}aimUI();};$('recenter').onclick=()=>{if(canPlay()&&!meter.active)recenter();};
function sampleSwing(speed,time,source){motionAt=time;lastSensorSource=source;meter.sample(speed,time);if(meter.active){$('meter').style.width=meter.power()*100+'%';$('swing-feedback').textContent=meter.power()>=.08?`${Math.round(meter.power()*100)}% power · release to shoot`:'Swing gently, then release to shoot.';}}
window.addEventListener('deviceorientation',e=>{const r=rotationMatrix(e.alpha,e.beta,e.gamma);if(!r)return;const now=performance.now(),speed=rotationSpeed(orientation,r,(now-orientationAt)/1000);orientation=r;orientationAt=now;if(now-gyroAt>200&&speed!==null)sampleSwing(speed,now,'orientation');if(turnAim&&canPlay()&&!meter.active&&!document.hidden){if(!steer.local)recenter(aim);aim=steer.sample(r);aimUI();}});
window.addEventListener('devicemotion',e=>{const r=e.rotationRate;if(!r||![r.alpha,r.beta,r.gamma].some(Number.isFinite))return;gyroAt=performance.now();sampleSwing(Math.hypot(r.alpha??0,r.beta??0,r.gamma??0),gyroAt,'gyroscope');});
let aimBusy=false;setInterval(async()=>{if(aimBusy||!canPlay()||meter.active||document.hidden||aim===lastSent)return;aimBusy=true;const value=aim;lastSent=value;await client.action({op:'aim',aim:value,turnNumber:match.turnNumber});aimBusy=false;},180);
async function fire(power,shotAim=aim,shotClub=club){if(!canPlay())return;const turnNumber=match.turnNumber;sending=true;controls();error('Sending your shot…');try{const id=typeof crypto.randomUUID==='function'?crypto.randomUUID():Array.from(crypto.getRandomValues(new Uint32Array(4)),n=>n.toString(16)).join('-');const r=await client.action({op:'shot',id,power,aim:shotAim,club:shotClub,turnNumber});if(r){navigator.vibrate?.(25);error('Shot sent! Watch the game screen.');}}catch{error('Shot could not be sent. Please try again.');}finally{sending=false;controls();}}
$('power').oninput=()=>$('powerlabel').textContent=$('power').value+'%';$('touchhit').onclick=()=>fire(Number($('power').value)/100);
const swing=$('swing');swing.onpointerdown=e=>{e.preventDefault();if(!canPlay()||pointer!==null)return;pointer=e.pointerId;lockedAim=aim;lockedClub=club;meter.start(performance.now());error('Keep holding, swing gently, then release to shoot.');$('meter').style.width='0%';swing.setPointerCapture(pointer);swing.classList.add('armed');controls();};
swing.onpointerup=e=>{if(pointer!==e.pointerId)return;pointer=null;const power=meter.finish(performance.now());swing.classList.remove('armed');if(power===null){const reason=meter.reason;if(turnAim)recenter(lockedAim);error({tap:'Hold the button while swinging, then release. A tap does not shoot.',long:'That hold was too long. Try a short swing and release.',sensor:'No usable motion readings. Tap Enable motion, or use Touch shot.',gentle:'Swing a little farther while holding, then release.'}[reason]??'Swing cancelled. Try again.');if(reason==='sensor')$('touch-controls').open=true;controls();}else fire(power,lockedAim,lockedClub);};
function cancel(){pointer=null;meter.cancel();swing.classList.remove('armed');if(turnAim)steer.local=null;controls();}swing.onpointercancel=cancel;swing.onlostpointercapture=()=>{if(pointer!==null)cancel();};document.addEventListener('visibilitychange',()=>{if(document.hidden)cancel();else steer.local=null;});screen.orientation?.addEventListener('change',()=>{steer.local=null;});
function controls(){const enabled=canPlay();swing.disabled=!enabled;$('touchhit').disabled=!enabled||meter.active;$('aim').disabled=!enabled||meter.active;$('motionaim').disabled=!enabled||meter.active;document.querySelectorAll('[data-club]').forEach(b=>{b.disabled=!enabled||meter.active;b.classList.toggle('selected',b.dataset.club===club);});$('swingtext').textContent=meter.active?'SWING, THEN RELEASE':sending?'SENDING SHOT…':enabled?'HOLD TO SWING':'WAIT FOR YOUR TURN';aimUI();}
function render(m){match=m;me=m.players.find(p=>p.id===session?.playerId);if(!session)return;if(!me){error('You were removed from the lobby. Reload to join again.');client.session=null;$('controller').hidden=true;$('join').hidden=false;session=null;sessionStorage.removeItem('fairway.pvp.player');return;}
 const mine=m.turn===me.id;if(turnKey!==m.turnNumber){turnKey=m.turnNumber;meter.cancel();pointer=null;swing.classList.remove('armed');aim=me.aim;club=me.club;steer.local=null;lastSent=null;if(turnAim&&orientation)recenter(aim);}
 $('phone-lobby').hidden=m.phase!=='lobby';$('play').hidden=m.phase==='lobby';$('lobbycode').textContent=`Lobby ${m.code}`;$('ready').textContent=me.ready?'Ready ✓ · tap to undo':'Ready to play ↗';
 $('phone-roster').innerHTML=m.players.map(p=>`<div class="roster-row"><i class="dot" style="background:${p.color}"></i><span class="grow">${escape(p.name)}</span><small>${!p.connected?'Offline':p.ready?'Ready ✓':'Not ready'}</small></div>`).join('');
 const current=m.players.find(p=>p.id===m.turn);$('turnstatus').classList.toggle('waiting',!mine);$('turnstatus').textContent=m.phase==='lobby'?`Welcome, ${me.name}`:me.forfeit?'You have forfeited':m.phase==='finished'?'Match complete':m.phase==='hole-complete'?'Hole complete · waiting for host':m.phase==='flight'?`${current?.name??'Golfer'}’s ball is in play`:mine?'Your turn · line up your shot':`${current?.name??'Golfer'}’s turn · watch the screen`;
 const h=HOLES[m.hole];$('holelabel').textContent=`Hole ${m.hole+1} / 6 · Par ${h.par}`;$('holename').textContent=h.name;$('strokes').textContent=me.strokes;$('distance').textContent=Math.round(Math.hypot(me.ball.x-h.pin.x,me.ball.z-h.pin.z))+' m';$('total').textContent=me.total+(me.done?0:me.strokes);
 $('phone-scores').innerHTML='<div class="eyebrow">Match scorecard</div>'+m.players.map(p=>`<div class="score-line"><span>${escape(p.name)}${p.forfeit?' · DNF':''}</span><strong>${p.total+(p.done?0:p.strokes)}</strong></div>`).join('');controls();
}
setInterval(()=>{$('sensor').textContent=performance.now()-motionAt<1500?'Motion is active. Short swings control power.':'Use HTTPS and allow motion, or use touch power.';if(!client.online)error('Reconnecting to the match…');controls();},1000);
window.__pvpPhone={client,get match(){return match;},get player(){return me;},fire};
